const K='sandro_performance_v1'; // mantém compatibilidade com a primeira versão
let db=JSON.parse(localStorage.getItem(K)||'{"daily":[],"training":[],"hiit":[],"cardio":[],"weights":[],"measures":[],"photos":[],"goals":{}}');
db.hiit=db.hiit||[];
db.profile=db.profile||{};
db.goals=db.goals||{};
if(db.goals.weight===undefined||db.goals.weight===null||db.goals.weight==='')db.goals.weight=75;
db.goals=db.goals||{};
db.integrations=db.integrations||{};
db.integrations.strava=db.integrations.strava||{connected:false,lastSync:null};
const $=x=>document.getElementById(x),today=()=>new Date().toISOString().slice(0,10),num=x=>+x||0;
let STRAVA_SERVICE_URL=(window.SPARTAN_STRAVA_SERVICE_URL||localStorage.getItem('spartan_strava_service_url')||'').replace(/\/$/,'');
['dDate','tDate','hDate','cDate','pDate','mDate','photoDate'].forEach(x=>$(x).value=today());
function openPage(pageId){
  document.querySelectorAll('.page').forEach(page=>page.classList.remove('on'));
  document.querySelectorAll('.nav button').forEach(button=>button.classList.remove('on'));

  const page=document.getElementById(pageId);
  const button=document.querySelector(`.nav button[data-p="${pageId}"]`);

  if(page)page.classList.add('on');
  if(button)button.classList.add('on');

  if(pageId==='hiit' && $('hDate') && !$('hDate').value){$('hDate').value=today();}

  if(pageId==='dash'){
    resetCalendarToToday();
    refreshV5Dashboard();
  }

  if(pageId==='profile')renderProfile();

  window.scrollTo({top:0,behavior:'smooth'});
}

document.querySelectorAll('.nav button').forEach(button=>{
  button.onclick=()=>{
    if(button.dataset.deezer){
      const deezerUrl=button.dataset.deezer;
      button.classList.add('on');
      setTimeout(()=>button.classList.remove('on'),650);
      window.location.href=deezerUrl;
      return;
    }
    openPage(button.dataset.p);
  };
});

document.querySelectorAll('[data-go]').forEach(button=>{
  button.onclick=()=>openPage(button.dataset.go);
});
function save(){
  localStorage.setItem(K,JSON.stringify(db));
  render();
  refreshV5Dashboard();
}
function totalDaily(){
  return ['dBreakfast','dLunch','dSnack','dDinner']
    .reduce((sum,id)=>{
      const field=$(id);
      return sum+(field?num(field.value):0);
    },0)+(num($('dCoffee')?.value)*2);
}

function loadDailyRecord(date){
  const selectedDate=date||today();
  const record=db.daily.find(x=>x.date===selectedDate);

  if($('dDate'))$('dDate').value=selectedDate;

  if(record){
    if($('dType'))$('dType').value=record.type||'Descanso';
    if($('dWater'))$('dWater').value=num(record.water);
    if($('dGoal'))$('dGoal').value=num(record.goal)||1900;
    if($('dBreakfast'))$('dBreakfast').value=num(record.breakfast);
    if($('dLunch'))$('dLunch').value=num(record.lunch);
    if($('dSnack'))$('dSnack').value=num(record.snack);
    if($('dDinner'))$('dDinner').value=num(record.dinner);
    if($('dCoffee'))$('dCoffee').value=num(record.coffee);
    if($('dCreatine'))$('dCreatine').checked=!!record.creatine;
    if($('dOmega'))$('dOmega').checked=!!record.omega;
    if($('dWhey'))$('dWhey').checked=!!record.whey;
    if($('dCarnitine'))$('dCarnitine').checked=!!record.carnitine;
    if($('dNotes'))$('dNotes').value=record.notes||'';
  }else{
    if($('dType'))$('dType').value='Descanso';
    if($('dWater'))$('dWater').value=0;
    if($('dGoal'))$('dGoal').value=1900;
    ['dBreakfast','dLunch','dSnack','dDinner'].forEach(id=>{if($(id))$(id).value=0;});
    if($('dCoffee'))$('dCoffee').value=0;
    ['dCreatine','dOmega','dWhey','dCarnitine'].forEach(id=>{if($(id))$(id).checked=false;});
    if($('dNotes'))$('dNotes').value='';
  }

  live();
  if(typeof refreshWaterQuick==='function')refreshWaterQuick();
  if(typeof refreshCoffeeUI==='function')refreshCoffeeUI();
}

function live(){
  const consumed=totalDaily();
  const goal=num($('dGoal')?.value)||1900;
  const remaining=goal-consumed;

  if($('dSum'))$('dSum').textContent=`Consumidas: ${consumed} · Restantes: ${remaining}`;
  if($('dBar'))$('dBar').style.width=Math.min(100,goal?consumed/goal*100:0)+'%';
}

['dBreakfast','dLunch','dSnack','dDinner','dGoal','dCoffee'].forEach(id=>{
  const field=$(id);
  if(field){
    field.addEventListener('input',live);
    field.addEventListener('change',live);
  }
});
live();

let waterHistory=[];
function waterGoalValue(){
  return num(db.goals?.water)||3000;
}
function refreshWaterQuick(){
  const total=num($('dWater').value);
  const goal=waterGoalValue();
  const remain=Math.max(0,goal-total);
  $('waterQuickTotal').textContent=`${total} ml`;
  $('waterQuickGoal').textContent=`Meta: ${goal} ml`;
  $('waterQuickRemain').textContent=remain?`Faltam ${remain} ml`:'Meta atingida';
  $('waterQuickBar').style.width=Math.min(100,goal?total/goal*100:0)+'%';
}
function addWater(amount){
  const current=num($('dWater').value);
  waterHistory.push(current);
  $('dWater').value=current+amount;
  refreshWaterQuick();
}
document.querySelectorAll('[data-water-add]').forEach(b=>{
  b.onclick=()=>addWater(num(b.dataset.waterAdd));
});
$('undoWater').onclick=()=>{
  if(!waterHistory.length)return;

  const value=waterHistory.pop();
  $('dWater').value=value;

  const date=$('dDate').value||today();
  let record=db.daily.find(x=>x.date===date);

  if(record){
    record.water=value;
  }else if(date===today()){
    record=getTodayRecord();
    record.water=value;
  }

  localStorage.setItem(K,JSON.stringify(db));
  refreshWaterQuick();
  refreshWaterQuickButton();
  refreshV5Dashboard();
};
$('resetWater').onclick=()=>{
  const current=num($('dWater').value);
  waterHistory.push(current);
  $('dWater').value=0;

  const date=$('dDate').value||today();
  let record=db.daily.find(x=>x.date===date);

  if(record){
    record.water=0;
  }else if(date===today()){
    record=getTodayRecord();
    record.water=0;
  }

  localStorage.setItem(K,JSON.stringify(db));
  refreshWaterQuick();
  refreshWaterQuickButton();
  refreshV5Dashboard();
};
$('dWater').addEventListener('input',refreshWaterQuick);

refreshWaterQuick();

$('resetCalories').onclick=()=>{
  ['dBreakfast','dLunch','dSnack','dDinner'].forEach(id=>{
    const field=$(id);
    if(field)field.value=0;
  });

  const date=$('dDate').value||today();
  const record=db.daily.find(x=>x.date===date);

  if(record){
    record.breakfast=0;
    record.lunch=0;
    record.snack=0;
    record.dinner=0;
    record.total=num(record.coffee)*2;
    localStorage.setItem(K,JSON.stringify(db));
  }

  live();
  refreshV5Dashboard();
  renderMainCalendar();
};

$('saveDaily').onclick=()=>{
  const date=$('dDate').value;
  const existingIndex=db.daily.findIndex(x=>x.date===date);
  const previous=existingIndex>=0?db.daily[existingIndex]:null;

  const record={
    id:previous?.id||crypto.randomUUID(),
    date,
    type:$('dType').value,
    water:num($('dWater').value),
    goal:num($('dGoal').value)||1900,
    breakfast:num($('dBreakfast').value),
    lunch:num($('dLunch').value),
    snack:num($('dSnack').value),
    dinner:num($('dDinner').value),
    coffee:num($('dCoffee')?.value),
    total:totalDaily(),
    creatine:$('dCreatine').checked,
    omega:$('dOmega').checked,
    whey:$('dWhey').checked,
    carnitine:$('dCarnitine').checked,
    notes:$('dNotes').value
  };

  if(existingIndex>=0)db.daily[existingIndex]=record;
  else db.daily.push(record);

  localStorage.setItem(K,JSON.stringify(db));
  loadDailyRecord(date);
  refreshV5Dashboard();
  renderMainCalendar();
  alert('Dia guardado');
};


