// Garante que TODOS os exercícios, atuais e futuros, seguem exatamente a ficha premium já existente.
function buildPremiumExerciseData(ex){
  const group=ex.group;
  const name=ex.name;
  const equipment=ex.equipment||'Peso corporal';
  const maps={
    'Peito':['Peitoral maior','Tríceps braquial e deltoide anterior','Mantém as omoplatas estáveis, os pulsos alinhados e controla a descida.'],
    'Costas':['Grande dorsal','Romboides, trapézio, bíceps braquial e braquial','Mantém o peito elevado e inicia o movimento aproximando as omoplatas.'],
    'Ombros':['Deltoides','Trapézio, tríceps e estabilizadores do ombro','Evita arquear a lombar e movimenta a carga de forma controlada.'],
    'Bíceps':['Bíceps braquial','Braquial e braquiorradial','Mantém os cotovelos junto ao tronco e evita embalar o corpo.'],
    'Tríceps':['Tríceps braquial','Deltoide anterior e estabilizadores do ombro','Mantém os cotovelos estáveis e completa a extensão sem perder o controlo.'],
    'Pernas':['Quadríceps','Glúteos, isquiotibiais, adutores e gémeos','Mantém os joelhos alinhados com os pés e o tronco firme.'],
    'Glúteos':['Glúteo máximo','Isquiotibiais, glúteo médio e core','Contrai os glúteos no topo sem exagerar a extensão lombar.'],
    'Core':['Reto abdominal e transverso abdominal','Oblíquos, lombar e estabilizadores da bacia','Mantém o abdómen contraído e evita perder a posição neutra da lombar.'],
    'Corpo inteiro':['Corpo inteiro','Pernas, glúteos, costas, ombros, braços e core','Executa cada fase com técnica e mantém o tronco estável.'],
    'Kettlebell':['Corpo inteiro','Glúteos, pernas, costas, ombros, braços e core','Mantém o kettlebell próximo do corpo e usa a anca quando o movimento for balístico.'],
    'HIIT':['Sistema cardiovascular e corpo inteiro','Pernas, glúteos, core, peito, ombros e braços conforme o movimento','Prioriza a técnica, mantém o tronco firme e adapta o ritmo à tua condição.']
  };
  let [primary,secondary,tip]=maps[group]||maps['Corpo inteiro'];
  const n=name.toLowerCase();
  if(/swing/.test(n)){primary='Glúteo máximo e isquiotibiais';secondary='Eretores da coluna, grande dorsal, deltoides, antebraços e core';tip='Impulsiona com a anca; não transformes o movimento numa elevação frontal.';}
  else if(/agachamento|squat|goblet/.test(n)){primary='Quadríceps e glúteo máximo';secondary='Isquiotibiais, adutores, gémeos e core';tip='Desce com o peito elevado e mantém os joelhos alinhados com a direção dos pés.';}
  else if(/peso morto|deadlift|romeno/.test(n)){primary='Isquiotibiais e glúteo máximo';secondary='Eretores da coluna, adutores, grande dorsal, antebraços e core';tip='Leva a anca para trás e mantém a coluna neutra durante todo o movimento.';}
  else if(/remada/.test(n)){primary='Grande dorsal e romboides';secondary='Trapézio médio, deltoide posterior, bíceps e braquial';tip='Puxa o cotovelo para trás sem rodar o tronco e controla a descida.';}
  else if(/press|thruster/.test(n)&&group!=='Peito'){primary='Deltoides';secondary='Tríceps, trapézio superior e core';tip='Mantém as costelas controladas e termina com a carga estável sobre o ombro.';}
  else if(/afundo|lunge|búlgaro/.test(n)){primary='Quadríceps e glúteo máximo';secondary='Isquiotibiais, glúteo médio, adutores, gémeos e core';tip='Mantém o joelho alinhado e distribui o peso de forma estável pelo pé da frente.';}
  else if(/flexões|flexões|push-up/.test(n)){primary='Peitoral maior';secondary='Tríceps braquial, deltoide anterior e core';tip='Mantém o corpo em linha reta e aproxima o peito do chão com controlo.';}
  else if(/prancha|plank|hollow|dead bug|bird dog|crunch|twist|wood chop|abdomin/.test(n)){primary='Core — reto abdominal, transverso e oblíquos';secondary='Lombar, glúteos e estabilizadores da cintura escapular';tip='Mantém a bacia controlada e respira sem perder a tensão abdominal.';}
  else if(/burpee|jumping|high knees|skater|saltos|jump squats|bear crawl/.test(n)){primary='Sistema cardiovascular e corpo inteiro';secondary='Quadríceps, glúteos, gémeos, core, ombros e braços';tip='Mantém um ritmo sustentável e reduz o impacto sempre que a técnica começar a falhar.';}
  const level=/burpee|snatch|clean & press|búlgaro|declinadas|high pull|thruster|bear crawl/i.test(name)?'Elevado':/máquina|inclinadas|bird dog|ponte de glúteos|dead bug/i.test(name)?'Baixo':'Intermédio';
  return {primary,secondary,equipment,level,tip,summary:`${primary}, ${secondary}.`};
}
(EX||[]).forEach(ex=>{if(!PREMIUM_EXERCISES[ex.name])PREMIUM_EXERCISES[ex.name]=buildPremiumExerciseData(ex);});

function refreshPremiumExerciseCard(){
  const card=document.getElementById('premiumExerciseCard');
  if(!card)return;
  const name=$('tExercise')?.value||'';
  const data=PREMIUM_EXERCISES[name];
  card.classList.toggle('active',!!data);
  if(!data)return;
  document.getElementById('premiumExerciseTitle').textContent=name;
  document.getElementById('premiumPrimary').textContent=data.primary;
  document.getElementById('premiumSecondary').textContent=data.secondary;
  document.getElementById('premiumEquipment').textContent=data.equipment;
  document.getElementById('premiumLevel').textContent=data.level;
  document.getElementById('premiumTip').textContent=data.tip;
}

const TRAINING_MUSCLES={
  'Peito':'Peitoral, tríceps e ombros anteriores.',
  'Costas':'Dorsais, trapézio, romboides, bíceps e lombar.',
  'Ombros':'Deltoides, trapézio e estabilizadores do ombro.',
  'Bíceps':'Bíceps, braquial e antebraço.',
  'Tríceps':'Tríceps e estabilizadores do ombro.',
  'Pernas':'Quadríceps, posteriores da coxa, glúteos e gémeos.',
  'Glúteos':'Glúteos, posteriores da coxa e zona abdominal.',
  'Core':'Abdominais, oblíquos, lombar e estabilizadores.'
};

function refreshTrainingMuscles(){
  const group=$('tGroup').value;
  const exercise=$('tExercise').value;
  const target=$('trainingMusclesText');
  if(!target)return;
  const premium=PREMIUM_EXERCISES[exercise];
  const muscles=premium?.summary||(TRAINING_MUSCLES[group]||'Grupo muscular principal do exercício selecionado.');
  target.innerHTML=`${exercise}: <strong class="muscle-glow">${muscles}</strong>`;
  refreshPremiumExerciseCard();
}

const groups=[...new Set(EX.filter(x=>x.group!=='HIIT').map(x=>x.group))];$('tGroup').innerHTML=groups.map(x=>`<option>${x}</option>`).join('');
let lastExerciseRecord=null;
function getLastExerciseRecord(){
  const name=$('tExercise').value;
  return db.training
    .filter(x=>x.exercise===name)
    .sort((a,b)=>b.date.localeCompare(a.date))[0]||null;
}
function updateTrainingMode(){
  $('series4Card').classList.add('fatigue');
  $('series4Card').querySelector('b').textContent='🔥 Série 4 — Até à fadiga';
  $('tFailure').value='true';
}
function showLastExercise(){
  lastExerciseRecord=getLastExerciseRecord();
  const btn=$('copyLastTraining');
  if(!lastExerciseRecord){
    $('lastSessionText').textContent='Ainda não existem registos deste exercício.';
    btn.style.display='none';
    return;
  }
  const reps=(lastExerciseRecord.reps||[]).slice(0,4);
  $('lastSessionText').innerHTML=
    `${lastExerciseRecord.date} · <b>${lastExerciseRecord.load||0} kg</b> · `+
    `reps ${reps.join(' / ')}`;
  btn.style.display='block';
}
function copyLastExercise(){
  if(!lastExerciseRecord)return;
  $('tLoad').value=lastExerciseRecord.load||0;
  const reps=lastExerciseRecord.reps||[];
  ['r1','r2','r3','r4'].forEach((id,i)=>$(id).value=reps[i]||'');
  $('tRest').value=lastExerciseRecord.rest||60;
  $('tNotes').value='';
  updateCurrentExerciseVolume();
}
function fillEx(){
  let a=EX.filter(x=>x.group===$('tGroup').value);
  $('tExercise').innerHTML=a.map(x=>`<option>${x.name}</option>`).join('');
  updateTrainingMode();
  showLastExercise();
  exerciseAnalysis();
  refreshTrainingMuscles();
}
$('tGroup').onchange=fillEx;
$('tExercise').onchange=()=>{showLastExercise();exerciseAnalysis();refreshTrainingMuscles()};
$('copyLastTraining').onclick=copyLastExercise;
fillEx();

function updateCurrentExerciseVolume(){
  const load=num($('tLoad').value);
  const reps=['r1','r2','r3','r4'].reduce((sum,id)=>sum+num($(id).value),0);
  const target=$('currentExerciseVolume');
  if(target)target.textContent=`${Math.round(load*reps*10)/10} kg`;
}

['tLoad','r1','r2','r3','r4'].forEach(id=>{
  $(id).addEventListener('input',updateCurrentExerciseVolume);
});

updateCurrentExerciseVolume();

$('saveTraining').onclick=()=>{
  const reps=[$('r1'),$('r2'),$('r3'),$('r4')].map(x=>num(x.value));
  const date=$('tDate').value;
  const exercise=$('tExercise').value;
  const existing=db.training.find(x=>x.date===date&&x.exercise===exercise);
  const record={
    id:existing?.id||crypto.randomUUID(),
    date,
    group:$('tGroup').value,
    exercise,
    load:num($('tLoad').value),
    sets:4,
    work:0,
    rest:num($('tRest').value)||60,
    reps,
    total:reps.reduce((a,b)=>a+b,0),
    failure:true,
    notes:$('tNotes').value
  };
  db.training=db.training.filter(x=>!(x.date===date&&x.exercise===exercise));
  db.training.push(record);
  save();
  showLastExercise();
  exerciseAnalysis();
  alert(existing?'Registo corrigido e atualizado.':'Exercício guardado. A 4.ª série ficou registada até à fadiga.');
};

$('resetTraining').onclick=()=>{
  const date=$('tDate').value;
  const exercise=$('tExercise').value;
  const matches=db.training.filter(x=>x.date===date&&x.exercise===exercise);
  if(matches.length&&confirm(`Apagar o registo de ${exercise} em ${date}?`)){
    db.training=db.training.filter(x=>!(x.date===date&&x.exercise===exercise));
    save();
    showLastExercise();
    exerciseAnalysis();
  }
  $('tLoad').value='';
  $('tRest').value=60;
  ['r1','r2','r3','r4'].forEach(id=>$(id).value='');
  $('tNotes').value='';
  updateCurrentExerciseVolume();
  if(!matches.length)alert('Não existe nenhum registo deste exercício nesta data.');
};



