function poseSvg(type,x){
  const skin='#f1d2b6', body='#e1b13d', dark='#25292d', line='#f4f0e8';
  const head=(cx,cy)=>`<circle cx="${x+cx}" cy="${cy}" r="13" fill="${skin}" stroke="${dark}" stroke-width="3"/>`;
  const limb=(x1,y1,x2,y2,w=11)=>`<line x1="${x+x1}" y1="${y1}" x2="${x+x2}" y2="${y2}" stroke="${line}" stroke-width="${w}" stroke-linecap="round"/>`;
  const torso=(x1,y1,x2,y2,w=18)=>`<line x1="${x+x1}" y1="${y1}" x2="${x+x2}" y2="${y2}" stroke="${body}" stroke-width="${w}" stroke-linecap="round"/>`;
  let s='';

  switch(type){
    case 'stand':
      s=head(75,38)+torso(75,55,75,113)+limb(75,70,42,101)+limb(75,70,108,101)+limb(75,113,50,158)+limb(75,113,100,158); break;
    case 'jump':
      s=head(75,26)+torso(75,43,75,99)+limb(75,60,34,25)+limb(75,60,116,25)+limb(75,99,42,151)+limb(75,99,108,151); break;
    case 'jack':
      s=head(75,35)+torso(75,52,75,105)+limb(75,64,24,24)+limb(75,64,126,24)+limb(75,105,30,160)+limb(75,105,120,160); break;
    case 'squat':
      s=head(78,52)+torso(76,68,61,112)+limb(70,82,31,105)+limb(70,82,111,102)+limb(61,112,104,124)+limb(104,124,124,164)+limb(61,112,30,158); break;
    case 'plank':
      s=head(34,89)+torso(52,93,111,111)+limb(64,97,51,153)+limb(86,104,78,156)+limb(111,111,144,149); break;
    case 'mountain':
      s=head(34,88)+torso(52,92,108,110)+limb(62,96,49,153)+limb(84,103,101,146)+limb(108,110,77,147); break;
    case 'high1':
      s=head(75,39)+torso(75,56,75,111)+limb(75,70,43,94)+limb(75,70,108,91)+limb(75,111,39,115)+limb(39,115,55,156)+limb(75,111,99,158); break;
    case 'high2':
      s=head(75,39)+torso(75,56,75,111)+limb(75,70,43,91)+limb(75,70,108,94)+limb(75,111,111,115)+limb(111,115,95,156)+limb(75,111,51,158); break;
    case 'pushTop':
      s=head(31,91)+torso(49,96,112,112)+limb(61,99,50,157)+limb(84,105,76,158)+limb(112,112,145,151); break;
    case 'pushBottom':
      s=head(31,119)+torso(49,119,112,124)+limb(61,120,43,153)+limb(84,122,64,156)+limb(112,124,145,151); break;
    case 'forearm':
      s=head(31,103)+torso(49,106,112,116)+limb(62,108,40,148)+limb(40,148,72,148)+limb(112,116,146,150); break;
    case 'side':
      s=head(40,99)+torso(57,104,111,119)+limb(69,107,51,150)+limb(51,150,83,150)+limb(80,111,78,52)+limb(111,119,147,150); break;
    case 'sitDown':
      s=head(32,136)+torso(50,139,98,142)+limb(98,142,125,111)+limb(125,111,151,148)+limb(60,139,83,113); break;
    case 'sitUp':
      s=head(53,72)+torso(65,88,97,135)+limb(97,135,125,111)+limb(125,111,151,148)+limb(71,94,104,75); break;
    default:
      s=head(75,38)+torso(75,55,75,113)+limb(75,70,42,101)+limb(75,70,108,101)+limb(75,113,50,158)+limb(75,113,100,158);
  }
  return `<g>${s}<line x1="${x+5}" y1="171" x2="${x+150}" y2="171" stroke="#42474c" stroke-width="3"/></g>`;
}

function exerciseImageSvg(sheet){
  const poses=sheet.poses||['stand'];
  const width=Math.max(330,poses.length*165);
  const figures=poses.map((pose,index)=>poseSvg(pose,index*165+5)).join('');
  const labels=poses.map((_,index)=>`<text x="${index*165+82}" y="198" text-anchor="middle" fill="#e1b13d" font-size="13" font-family="Arial" font-weight="700">FASE ${index+1}</text>`).join('');
  return `<svg viewBox="0 0 ${width} 215" xmlns="http://www.w3.org/2000/svg" role="img">
    <rect width="100%" height="100%" fill="#111519"/>
    ${figures}
    ${labels}
  </svg>`;
}

