function drawLine(canvas,arr,valueFn,color='#d7b84d',empty='Sem dados suficientes.'){let c=$(canvas),ctx=c.getContext('2d'),dpr=devicePixelRatio||1;c.width=c.clientWidth*dpr;c.height=c.clientHeight*dpr;ctx.scale(dpr,dpr);let w=c.clientWidth,h=c.clientHeight;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#303030';for(let i=0;i<5;i++){let y=20+i*(h-40)/4;ctx.beginPath();ctx.moveTo(35,y);ctx.lineTo(w-10,y);ctx.stroke()}if(arr.length<2){ctx.fillStyle='#aaa';ctx.fillText(empty,20,h/2);return}let vals=arr.map(valueFn),min=Math.min(...vals),max=Math.max(...vals);if(min===max){min-=1;max+=1}ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();arr.forEach((x,i)=>{let px=35+i*(w-55)/(arr.length-1),py=20+(max-valueFn(x))*(h-40)/(max-min);i?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.stroke();ctx.fillStyle=color;arr.forEach((x,i)=>{let px=35+i*(w-55)/(arr.length-1),py=20+(max-valueFn(x))*(h-40)/(max-min);ctx.beginPath();ctx.arc(px,py,3.5,0,Math.PI*2);ctx.fill()})}
function getExerciseRecords(){
  const n=$('tExercise').value;
  return db.training.filter(x=>x.exercise===n).sort((a,b)=>a.date.localeCompare(b.date));
}
function calculateVolume(record){return num(record.load)*num(record.total)}
function suggestNextLoad(records){
  if(!records.length)return null;
  const last=records[records.length-1],reps=(last.reps||[]).slice(0,4),valid=reps.filter(x=>num(x)>0);
  if(!valid.length)return num(last.load)||0;
  const firstThree=reps.slice(0,3).filter(x=>num(x)>0);
  const average=firstThree.length?firstThree.reduce((a,b)=>a+num(b),0)/firstThree.length:valid.reduce((a,b)=>a+num(b),0)/valid.length;
  const minimum=Math.min(...valid.map(num)),current=num(last.load)||0;
  if(average>=12&&minimum>=8)return Math.round((current+2.5)*2)/2;
  if(average<8||minimum<6)return Math.max(0,Math.round((current-2.5)*2)/2);
  return current;
}
function renderTrainingProgress(){
  const records=getExerciseRecords();
  if(!records.length){
    $('prLoad').textContent='—';$('prVolume').textContent='—';$('trainingTrend').textContent='—';
    $('trainingTrend').className='';$('nextLoadSuggestion').textContent='—';
    $('progressAdvice').textContent='Regista este exercício para começar a acompanhar a evolução.';
    $('recordNotice').style.display='none';return;
  }
  const last=records[records.length-1],previous=records.length>1?records[records.length-2]:null;
  const maxLoad=Math.max(...records.map(x=>num(x.load))),maxVolume=Math.max(...records.map(calculateVolume)),next=suggestNextLoad(records);
  $('prLoad').textContent=`${maxLoad} kg`;$('prVolume').textContent=`${Math.round(maxVolume)} kg`;
  $('nextLoadSuggestion').textContent=`${next} kg`;
  let trend='Primeiro registo',trendClass='trend-flat';
  if(previous){
    const diff=calculateVolume(last)-calculateVolume(previous),prevVol=calculateVolume(previous);
    if(diff>0){trend=`↑ +${prevVol?Math.round(diff/prevVol*100):0}%`;trendClass='trend-up'}
    else if(diff<0){trend=`↓ -${prevVol?Math.round(Math.abs(diff)/prevVol*100):0}%`;trendClass='trend-down'}
    else{trend='→ Igual';trendClass='trend-flat'}
  }
  $('trainingTrend').textContent=trend;$('trainingTrend').className=trendClass;
  const load=num(last.load),volume=calculateVolume(last);
  const loadCount=records.filter(x=>num(x.load)===maxLoad).length;
  const volCount=records.filter(x=>calculateVolume(x)===maxVolume).length;
  const isLoadPR=load===maxLoad&&loadCount===1,isVolumePR=volume===maxVolume&&volCount===1;
  if(isLoadPR||isVolumePR){
    const labels=[];if(isLoadPR)labels.push('novo PR de carga');if(isVolumePR)labels.push('novo PR de volume');
    $('recordNotice').textContent=`🏆 ${labels.join(' e ')}!`;$('recordNotice').style.display='block';
  }else{$('recordNotice').style.display='none'}
  if(next>load)$('progressAdvice').textContent=`Boa evolução. Na próxima sessão, experimenta ${next} kg.`;
  else if(next<load)$('progressAdvice').textContent=`A execução ficou abaixo do objetivo. Considera ${next} kg para recuperar qualidade.`;
  else $('progressAdvice').textContent=`Mantém ${next} kg e tenta melhorar as repetições antes de aumentar a carga.`;
}
function exerciseAnalysis(){
  const exerciseSelect=$('tExercise');
  if(!exerciseSelect)return;

  const name=exerciseSelect.value;
  const records=db.training
    .filter(x=>x.exercise===name)
    .sort((a,b)=>a.date.localeCompare(b.date));

  const evolution=$('simpleTrainingEvolution');
  const stats=$('exerciseStats');
  const chart=$('exerciseChart');

  if(!records.length){
    if(evolution)evolution.textContent='Ainda sem registos deste exercício.';
    if(stats)stats.textContent='Ainda sem registos deste exercício.';
    if(chart)drawLine('exerciseChart',[],x=>x);
    return;
  }

  const first=records[0];
  const last=records[records.length-1];

  if(evolution){
    const loadDiff=num(last.load)-num(first.load);
    const repsDiff=num(last.total)-num(first.total);
    evolution.innerHTML=
      `Carga: <b>${first.load} kg → ${last.load} kg</b><br>`+
      `Repetições totais: <b>${first.total} → ${last.total}</b><br>`+
      `Alteração: <b>${loadDiff>=0?'+':''}${loadDiff} kg</b> · `+
      `<b>${repsDiff>=0?'+':''}${repsDiff} repetições</b>`;
  }

  if(stats){
    stats.innerHTML=
      `<strong>${name}</strong><br>`+
      `Primeiro: ${first.load} kg · ${first.total} repetições<br>`+
      `Último: ${last.load} kg · ${last.total} repetições`;
  }

  if(chart){
    drawLine('exerciseChart',records.slice(-12),x=>num(x.load),'#d7b84d','Regista pelo menos 2 treinos deste exercício.');
  }
}

function score(){let d=db.daily.find(x=>x.date===today()),waterGoal=db.goals.water||3000,month=today().slice(0,7),trainGoal=db.goals.train||20;let water=d?Math.min(1,d.water/waterGoal):0,kcal=d?Math.max(0,1-Math.abs(d.total-d.goal)/Math.max(d.goal,1)):0,train=Math.min(1,db.training.filter(x=>x.date.startsWith(month)).length/trainGoal);let w=water*.3+kcal*.3+train*.4,s=Math.round(w*100);$('scoreValue').textContent=s;$('scoreRing').style.background=`conic-gradient(#d7b84d ${s*3.6}deg,#272727 0deg)`;$('scoreLabel').textContent=s>=85?'Excelente':s>=65?'Boa consistência':s>=40?'A melhorar':'A iniciar';$('scoreInfo').textContent=`Água ${Math.round(water*100)}% · Calorias ${Math.round(kcal*100)}% · Treino ${Math.round(train*100)}%`}
function dashboard(){let d=db.daily.find(x=>x.date===today());$('kKcal').textContent=d?`${d.total}/${d.goal}`:'0/1900';$('kWater').textContent=d?`${d.water}/${db.goals.water||3000}`:`0/${db.goals.water||3000}`;let m=today().slice(0,7);$('kSessions').textContent=db.training.filter(x=>x.date.startsWith(m)).length+(db.hiit||[]).filter(x=>x.date.startsWith(m)).length+db.cardio.filter(x=>x.date.startsWith(m)).length;let w=[...db.weights].sort((a,b)=>b.date.localeCompare(a.date))[0];$('kWeight').textContent=w?`${w.weight} kg`:'—';score();week();records();calendar();goals()}
function week(){let now=new Date(),start=new Date(now);start.setDate(now.getDate()-6);let iso=d=>d.toISOString().slice(0,10),s=iso(start),e=iso(now);let tr=db.training.filter(x=>x.date>=s&&x.date<=e),hi=(db.hiit||[]).filter(x=>x.date>=s&&x.date<=e),ca=db.cardio.filter(x=>x.date>=s&&x.date<=e),days=db.daily.filter(x=>x.date>=s&&x.date<=e),avgW=days.length?Math.round(days.reduce((a,b)=>a+b.water,0)/days.length):0,avgK=days.length?Math.round(days.reduce((a,b)=>a+b.total,0)/days.length):0,km=ca.reduce((a,b)=>a+b.distance,0);$('weekSummary').innerHTML=`Musculação: <b>${tr.length}</b><br>HIIT: <b>${hi.length}</b><br>Cardio: <b>${ca.length}</b> sessões · <b>${km.toFixed(1)} km</b><br>Água média: <b>${avgW} ml</b><br>Calorias médias: <b>${avgK}</b>`}
