function calendar(){
  const now=new Date();
  const today=todayISO();
  let y=calendarCursor.getFullYear(),m=calendarCursor.getMonth();
  $('calendarTitle').textContent=new Intl.DateTimeFormat('pt-PT',{month:'long',year:'numeric'}).format(calendarCursor);
  let days=new Date(y,m+1,0).getDate(),first=new Date(y,m,1).getDay(),html='';
  for(let i=0;i<(first+6)%7;i++)html+='<div></div>';
  for(let d=1;d<=days;d++){
    let date=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,
        hasStrength=db.training.some(x=>x.date===date),
        hasHiit=(db.hiit||[]).some(x=>x.date===date),
        hasCardio=db.cardio.some(x=>x.date===date),
        typeClass=(hasStrength||hasHiit||hasCardio)?'train':'',
        todayClass=date===today?' today':'',
        cls='day '+typeClass+todayClass;
    const dots=[hasStrength?'strength':'',hasHiit?'hiit':'',hasCardio?'cardio':''].filter(Boolean).map(kind=>`<i class="sf-day-dot ${kind}"></i>`).join('');
    html+=`<button class="${cls}" data-date="${date}" aria-label="${date===today?'Hoje, ':''}abrir ${date}"><span>${d}</span>${dots?`<span class="sf-day-dots">${dots}</span>`:''}</button>`;
  }
  $('calendar').innerHTML=html;
  $('calendar').querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>openCalendarDay(b.dataset.date));
}
