function goals(){$('goalTrain').value=db.goals.train||20;$('goalWater').value=db.goals.water||3000;$('goalWeight').value=(db.goals.weight??75);let m=today().slice(0,7),t=db.training.filter(x=>x.date.startsWith(m)).length+(db.hiit||[]).filter(x=>x.date.startsWith(m)).length+db.cardio.filter(x=>x.date.startsWith(m)).length,tg=db.goals.train||20,weights=[...db.weights].sort((a,b)=>b.date.localeCompare(a.date)),cw=weights[0]?.weight,gw=db.goals.weight;$('goalsView').innerHTML=`<div class="goal">Sessões do mês: <b>${t}/${tg}</b><div class="bar"><i style="width:${Math.min(100,t/tg*100)}%"></i></div></div>`+(gw?`<div class="goal">Peso atual: <b>${cw??'—'} kg</b> · Alvo: <b>${gw} kg</b></div>`:'')}
function cardioStats(){
  let a=db.cardio,
      km=a.reduce((s,x)=>s+num(x.distance),0),
      min=a.reduce((s,x)=>s+num(x.duration),0),
      calories=a.reduce((s,x)=>s+num(x.calories),0),
      best=[...a].sort((x,y)=>num(y.distance)-num(x.distance))[0],
      byType={};

  a.forEach(x=>byType[x.type]=(byType[x.type]||0)+1);

  const types=Object.entries(byType)
    .map(([type,count])=>`${type}: <b>${count}</b>`)
    .join('<br>');

  $('cardioStats').innerHTML=
    `Sessões: <b>${a.length}</b><br>`+
    `Distância total: <b>${km.toFixed(1)} km</b><br>`+
    `Tempo total: <b>${min} min</b><br>`+
    `Calorias registadas: <b>${calories}</b><br>`+
    `Maior distância: <b>${best?best.distance+' km ('+best.type+')':'—'}</b>`+
    (best&&num(best.avgSpeed)>0?`<br>Velocidade média do melhor registo: <b>${num(best.avgSpeed).toFixed(1)} km/h</b>`:'')+
    (types?`<br><br>${types}`:'');
}
