let intensityCursor=new Date();
function bestBy(list,score){
  return list.reduce((best,item)=>!best||score(item)>score(best)?item:best,null);
}
function recordItem(title,main,date,target=''){
  return `<div class="record-row"><div><strong>${title}</strong><span>${main}</span>${target?`<small>Próximo objetivo: ${target}</small>`:''}</div><b class="record-date">${date||'—'}</b></div>`;
}
function history(){
  const trBy={};
  db.training.forEach(x=>{
    const key=x.exercise||'Exercício';
    const score=num(x.load)*100000+num(x.total);
    if(!trBy[key]||score>trBy[key]._score)trBy[key]={...x,_score:score};
  });
  const tr=Object.values(trBy).sort((a,b)=>a.exercise.localeCompare(b.exercise,'pt'));
  $('recordMusculation').innerHTML=`<h3><img class="v840-record-row-icon" src="data:image/jpeg;base64," alt="">Musculação</h3>`+(tr.length?tr.map(x=>recordItem(x.exercise,`${num(x.load)} kg · ${num(x.total)} repetições`,x.date,`${num(x.load)+1} kg ou mais repetições`)).join(''):'<p class="small">Ainda sem recordes.</p>');

  const hiBy={};
  (db.hiit||[]).forEach(x=>{
    const key=x.exercise||'Exercício HIIT';
    const score=num(x.total)*1000+num(x.calories);
    if(!hiBy[key]||score>hiBy[key]._score)hiBy[key]={...x,_score:score};
  });
  const hi=Object.values(hiBy).sort((a,b)=>(a.exercise||'').localeCompare(b.exercise||'','pt'));
  $('recordHiit').innerHTML=`<h3><img class="v840-record-row-icon" src="data:image/jpeg;base64," alt="">HIIT</h3>`+(hi.length?hi.map(x=>{
    const unit=x.mode==='seconds'?'segundos':'repetições';
    return recordItem(x.exercise||'Exercício',`${num(x.total)} ${unit} · ${num(x.calories)} kcal`,x.date,`${num(x.total)+1} ${unit}`);
  }).join(''):'<p class="small">Ainda sem recordes.</p>');

  const caBy={};
  (db.cardio||[]).forEach(x=>{
    const key=x.type||'Cardio';
    const score=num(x.distance)*100000+num(x.calories)*10+num(x.duration);
    if(!caBy[key]||score>caBy[key]._score)caBy[key]={...x,_score:score};
  });
  const ca=Object.values(caBy).sort((a,b)=>(a.type||'').localeCompare(b.type||'','pt'));
  $('recordCardio').innerHTML=`<h3><img class="v840-record-row-icon" src="data:image/jpeg;base64," alt="">Cardio</h3>`+(ca.length?ca.map(x=>recordItem(x.type||'Cardio',`${num(x.distance).toFixed(1)} km · ${num(x.duration)} min · ${num(x.calories)} kcal`,x.date,`${(num(x.distance)+1).toFixed(1)} km`)).join(''):'<p class="small">Ainda sem recordes.</p>');

  const bestTraining=bestBy(db.training,x=>num(x.load)*num(x.total));
  const bestHiit=bestBy(db.hiit||[],x=>num(x.calories));
  const bestCardio=bestBy(db.cardio||[],x=>num(x.calories));
  const general=[];
  if(bestTraining)general.push(recordItem('Maior volume de musculação',`${Math.round(num(bestTraining.load)*num(bestTraining.total))} kg · ${bestTraining.exercise}`,bestTraining.date));
  if(bestHiit)general.push(recordItem('Mais calorias em HIIT',`${num(bestHiit.calories)} kcal · ${bestHiit.exercise||'HIIT'}`,bestHiit.date,`${num(bestHiit.calories)+1} kcal`));
  if(bestCardio)general.push(recordItem('Mais calorias em cardio',`${num(bestCardio.calories)} kcal · ${bestCardio.type||'Cardio'}`,bestCardio.date,`${num(bestCardio.calories)+1} kcal`));
  $('recordGeneral').innerHTML='<h3><img class="v840-record-header-icon" src="data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20viewBox%3D%220%200%2064%2064%22%3E%0A%3Cdefs%3E%0A%20%3ClinearGradient%20id%3D%22g%22%20x1%3D%220%22%20y1%3D%220%22%20x2%3D%221%22%20y2%3D%221%22%3E%3Cstop%20stop-color%3D%22%23fff0a5%22%2F%3E%3Cstop%20offset%3D%22.35%22%20stop-color%3D%22%23d59a2c%22%2F%3E%3Cstop%20offset%3D%22.72%22%20stop-color%3D%22%237a430f%22%2F%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%23e1b44c%22%2F%3E%3C%2FlinearGradient%3E%0A%20%3ClinearGradient%20id%3D%22b%22%20x1%3D%220%22%20y1%3D%220%22%20x2%3D%220%22%20y2%3D%221%22%3E%3Cstop%20stop-color%3D%22%231a1713%22%2F%3E%3Cstop%20offset%3D%221%22%20stop-color%3D%22%23050505%22%2F%3E%3C%2FlinearGradient%3E%0A%20%3Cfilter%20id%3D%22sh%22%3E%3CfeDropShadow%20dx%3D%220%22%20dy%3D%222%22%20stdDeviation%3D%221.5%22%20flood-color%3D%22%23000%22%20flood-opacity%3D%22.8%22%2F%3E%3C%2Ffilter%3E%0A%3C%2Fdefs%3E%0A%3Crect%20x%3D%222%22%20y%3D%222%22%20width%3D%2260%22%20height%3D%2260%22%20rx%3D%2213%22%20fill%3D%22url%28%23b%29%22%20stroke%3D%22%238e5d1c%22%20stroke-width%3D%222%22%2F%3E%0A%3Crect%20x%3D%226%22%20y%3D%226%22%20width%3D%2252%22%20height%3D%2252%22%20rx%3D%2210%22%20fill%3D%22none%22%20stroke%3D%22%23d5a545%22%20stroke-opacity%3D%22.42%22%2F%3E%0A%3Cg%20fill%3D%22url%28%23g%29%22%20stroke%3D%22%233b2108%22%20stroke-width%3D%22.8%22%20filter%3D%22url%28%23sh%29%22%3E%3Cpath%20d%3D%22m11%2011%2020%2020-6%206-5-5-5%205-6-6%206-6-4-4V11Zm42%200v10l-4%204%206%206-6%206-5-5-5%205-6-6%2020-20ZM23%2039l6%206-12%2012H8v-9l15-9Zm18%200%2015%209v9h-9L35%2045l6-6Z%22%2F%3E%3C%2Fg%3E%0A%3C%2Fsvg%3E" alt="">Recordes gerais</h3>'+(general.length?general.join(''):'<p class="small">Ainda sem recordes.</p>');
  drawIntensityChart();
}
function dailyIntensityData(){
  const ym=`${intensityCursor.getFullYear()}-${String(intensityCursor.getMonth()+1).padStart(2,'0')}`;
  const raw={};
  db.training.filter(x=>x.date.startsWith(ym)).forEach(x=>raw[x.date]=(raw[x.date]||0)+num(x.load)*num(x.total));
  (db.hiit||[]).filter(x=>x.date.startsWith(ym)).forEach(x=>raw[x.date]=(raw[x.date]||0)+num(x.total)*2+num(x.calories)*3);
  (db.cardio||[]).filter(x=>x.date.startsWith(ym)).forEach(x=>raw[x.date]=(raw[x.date]||0)+num(x.distance)*35+num(x.duration)*2+num(x.calories)*2);
  const rows=Object.entries(raw).sort((a,b)=>a[0].localeCompare(b[0]));
  const max=Math.max(1,...rows.map(x=>x[1]));
  return rows.map(([date,value])=>({date,value:Math.max(8,Math.round(value/max*100))}));
}
function drawIntensityChart(){
  const title=$('intensityMonth');
  const canvas=$('intensityChart');
  if(!title||!canvas)return;
  title.textContent=new Intl.DateTimeFormat('pt-PT',{month:'long',year:'numeric'}).format(intensityCursor);
  const data=dailyIntensityData();
  const ctx=canvas.getContext('2d');
  const dpr=window.devicePixelRatio||1;
  const w=canvas.clientWidth||320,h=canvas.clientHeight||230;
  canvas.width=w*dpr;canvas.height=h*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);
  ctx.clearRect(0,0,w,h);
  if(!data.length){ctx.fillStyle='#888';ctx.font='13px sans-serif';ctx.textAlign='center';ctx.fillText('Sem treinos neste mês.',w/2,h/2);return;}
  const pad={l:34,r:14,t:18,b:34},cw=w-pad.l-pad.r,ch=h-pad.t-pad.b;
  ctx.strokeStyle='rgba(255,255,255,.10)';ctx.lineWidth=1;
  [0,25,50,75,100].forEach(v=>{const y=pad.t+ch-(v/100)*ch;ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();});
  const x=i=>data.length===1?pad.l+cw/2:pad.l+i*cw/(data.length-1);
  const y=v=>pad.t+ch-(v/100)*ch;
  const grad=ctx.createLinearGradient(0,pad.t,0,pad.t+ch);grad.addColorStop(0,'#ffd84a');grad.addColorStop(1,'#ff5a00');
  ctx.strokeStyle=grad;ctx.lineWidth=3;ctx.shadowColor='#ffb000';ctx.shadowBlur=10;ctx.beginPath();data.forEach((p,i)=>i?ctx.lineTo(x(i),y(p.value)):ctx.moveTo(x(i),y(p.value)));ctx.stroke();ctx.shadowBlur=0;
  data.forEach((p,i)=>{ctx.fillStyle='#ff263f';ctx.beginPath();ctx.arc(x(i),y(p.value),4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#aaa';ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillText(String(Number(p.date.slice(8))),x(i),h-12);});
}

