function calculateProfileAge(birthDate){
  if(!birthDate)return '';
  const birth=new Date(birthDate+'T00:00:00');
  if(Number.isNaN(birth.getTime()))return '';

  const now=new Date();
  let age=now.getFullYear()-birth.getFullYear();
  const monthDifference=now.getMonth()-birth.getMonth();

  if(monthDifference<0 || (monthDifference===0 && now.getDate()<birth.getDate())){
    age--;
  }

  return age>=0?`${age} anos`:'';
}

function renderProfile(){
  const profile=db.profile||{};

  if($('profileName'))$('profileName').value=profile.name||'';
  if($('profileBirthDate'))$('profileBirthDate').value=profile.birthDate||'';
  if($('profileAge'))$('profileAge').value=calculateProfileAge(profile.birthDate);
  if($('profileHeight'))$('profileHeight').value=profile.height||'';
  if($('profileStartDate'))$('profileStartDate').value=profile.startDate||'';

  const weights=[...db.weights]
    .filter(item=>num(item.weight)>0)
    .sort((a,b)=>a.date.localeCompare(b.date));

  const goal=num(db.goals.weight)||75;

  if($('profileGoalWeight')){
    $('profileGoalWeight').textContent=`${goal.toFixed(1)} kg`;
  }

  if(!weights.length){
    if($('profileStartWeight'))$('profileStartWeight').textContent='—';
    if($('profileCurrentWeight'))$('profileCurrentWeight').textContent='—';
    if($('profileWeightProgress'))$('profileWeightProgress').textContent='—';
    return;
  }

  const first=num(weights[0].weight);
  const current=num(weights[weights.length-1].weight);
  const change=current-first;
  const remaining=Math.abs(current-goal);

  if($('profileStartWeight'))$('profileStartWeight').textContent=`${first.toFixed(1)} kg`;
  if($('profileCurrentWeight'))$('profileCurrentWeight').textContent=`${current.toFixed(1)} kg`;

  if($('profileWeightProgress')){
    if(remaining<0.05){
      $('profileWeightProgress').textContent='Objetivo atingido';
    }else if(change<0){
      $('profileWeightProgress').textContent=`-${Math.abs(change).toFixed(1)} kg · faltam ${remaining.toFixed(1)} kg`;
    }else if(change>0){
      $('profileWeightProgress').textContent=`+${change.toFixed(1)} kg · faltam ${remaining.toFixed(1)} kg`;
    }else{
      $('profileWeightProgress').textContent=`Sem alteração · faltam ${remaining.toFixed(1)} kg`;
    }
  }
}

