function refreshV5Dashboard(){
  const date=today();
  const todayRecord=db.daily.find(x=>x.date===date);
  const consumed=todayRecord?num(todayRecord.total):0;

  const hiitBurned=(db.hiit||[])
    .filter(x=>x.date===date)
    .reduce((sum,x)=>sum+num(x.calories),0);

  const cardioBurned=(db.cardio||[])
    .filter(x=>x.date===date)
    .reduce((sum,x)=>sum+num(x.calories),0);

  const burned=hiitBurned+cardioBurned;
  const target=todayRecord?num(todayRecord.goal)||1900:1900;
  const balance=Math.max(0,target-consumed+burned);
  const pct=Math.max(0,Math.min(100,consumed/target*100));

  const ring=$('v5CalorieRing');
  if(ring){
    ring.style.background=`conic-gradient(#e1b13d 0deg ${pct*3.6}deg,#2d2d2d ${pct*3.6}deg 360deg)`;
  }

  if($('v5KcalConsumed'))$('v5KcalConsumed').textContent=consumed;
  if($('v5ConsumedStat'))$('v5ConsumedStat').textContent=`${consumed} kcal`;
  if($('v5BurnedStat'))$('v5BurnedStat').textContent=`${burned} kcal`;
  if($('v5RemainingStat'))$('v5RemainingStat').textContent=`${balance} kcal`;

  const month=date.slice(0,7);
  const set=(id,val)=>{const el=$(id);if(el)el.textContent=val};
  set('v5Muscle',db.training.filter(x=>x.date.startsWith(month)).length);
  set('v5Hiit',(db.hiit||[]).filter(x=>x.date.startsWith(month)).length);
  set('v5Cardio',(db.cardio||[]).filter(x=>x.date.startsWith(month)).length);
  set('v5Food',db.daily.filter(x=>
    x.date.startsWith(month) &&
    (num(x.breakfast)+num(x.lunch)+num(x.snack)+num(x.dinner))>0
  ).length);
  set('v5Measures',db.measures.filter(x=>x.date.startsWith(month)).length);

  refreshWaterQuickButton();
  drawGoalProgressChart();
  renderMainCalendar();
}







function drawGoalProgressChart(){
  const canvas=$('v5GoalProgressChart');
  if(!canvas)return;

  const ctx=canvas.getContext('2d');
  const rect=canvas.getBoundingClientRect();
  const dpr=window.devicePixelRatio||1;
  canvas.width=Math.max(320,rect.width*dpr);
  canvas.height=220*dpr;
  ctx.setTransform(dpr,0,0,dpr,0,0);

  const width=canvas.width/dpr;
  const height=220;
  ctx.clearRect(0,0,width,height);

  const weights=[...db.weights]
    .filter(x=>num(x.weight)>0)
    .sort((a,b)=>a.date.localeCompare(b.date));

  const goal=num(db.goals.weight)||75;

  if($('v5GoalWeightInput'))$('v5GoalWeightInput').value=goal;
  if($('v5TargetWeight'))$('v5TargetWeight').textContent=`${goal.toFixed(1)} kg`;
  if($('v5MissionGoalTitle'))$('v5MissionGoalTitle').textContent=`${goal.toFixed(0)} KG`;
  if($('v5ProgressGoalLabel'))$('v5ProgressGoalLabel').textContent=`${goal.toFixed(1)} kg`;

  if(!weights.length){
    if($('v5StartWeight'))$('v5StartWeight').textContent='—';
    if($('v5CurrentWeight'))$('v5CurrentWeight').textContent='—';
    if($('v5WeightRemaining'))$('v5WeightRemaining').textContent='—';
    if($('v5GoalProgressText'))$('v5GoalProgressText').textContent=`${goal.toFixed(1)} kg`;
    if($('v5MissionPercent'))$('v5MissionPercent').textContent='0%';
    if($('v5MissionProgressBar'))$('v5MissionProgressBar').style.width='0%';
    if($('v5ProgressStartLabel'))$('v5ProgressStartLabel').textContent='—';
    if($('v5MissionMessage'))$('v5MissionMessage').textContent='Regista a primeira pesagem para iniciar a missão.';
    if($('v5StartDate'))$('v5StartDate').textContent='Sem registo';
    if($('v5CurrentDate'))$('v5CurrentDate').textContent='Sem registo';
    if($('v5BestWeight'))$('v5BestWeight').textContent='—';
    if($('v5BestWeightDate'))$('v5BestWeightDate').textContent='—';
    if($('v5WeightDays'))$('v5WeightDays').textContent='0';
    if($('v5WeightEvolution'))$('v5WeightEvolution').textContent='—';
    if($('v5NextMilestone'))$('v5NextMilestone').textContent='—';

    ctx.fillStyle='#aaa';
    ctx.font='14px sans-serif';
    ctx.textAlign='center';
    ctx.fillText('Regista a primeira pesagem para iniciar a evolução.',width/2,height/2);
    return;
  }

  const first=num(weights[0].weight);
  const latest=num(weights[weights.length-1].weight);
  const totalDistance=Math.abs(first-goal);
  const currentDistance=Math.abs(latest-goal);
  const progress=totalDistance===0
    ?100
    :Math.max(0,Math.min(100,(1-currentDistance/totalDistance)*100));
  const remaining=Math.abs(latest-goal);

  if($('v5StartWeight'))$('v5StartWeight').textContent=`${first.toFixed(1)} kg`;
  if($('v5CurrentWeight'))$('v5CurrentWeight').textContent=`${latest.toFixed(1)} kg`;
  if($('v5WeightRemaining'))$('v5WeightRemaining').textContent=
    remaining<0.05?'Objetivo atingido':`${remaining.toFixed(1)} kg`;

  if($('v5GoalProgressText'))$('v5GoalProgressText').textContent=`${goal.toFixed(1)} kg`;
  if($('v5MissionPercent'))$('v5MissionPercent').textContent=`${Math.round(progress)}%`;
  if($('v5MissionProgressBar'))$('v5MissionProgressBar').style.width=`${progress}%`;
  if($('v5ProgressStartLabel'))$('v5ProgressStartLabel').textContent=`${first.toFixed(1)} kg`;
  if($('v5MissionMessage'))$('v5MissionMessage').innerHTML=
    remaining<0.05
      ?'<span>Missão cumprida. Objetivo alcançado!</span>'
      :`Faltam <span>${remaining.toFixed(1)} kg</span> para cumprir a missão.`;

  const formatDate=s=>{
    if(!s)return '—';
    const p=s.split('-');
    return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:s;
  };
  if($('v5StartDate'))$('v5StartDate').textContent=`Registado em ${formatDate(weights[0].date)}`;
  if($('v5CurrentDate'))$('v5CurrentDate').textContent=`Atualizado em ${formatDate(weights[weights.length-1].date)}`;

  const best=weights.reduce((a,b)=>num(b.weight)<num(a.weight)?b:a,weights[0]);
  if($('v5BestWeight'))$('v5BestWeight').textContent=`${num(best.weight).toFixed(1)} kg`;
  if($('v5BestWeightDate'))$('v5BestWeightDate').textContent=formatDate(best.date);
  if($('v5WeightDays'))$('v5WeightDays').textContent=String(new Set(weights.map(x=>x.date)).size);
  if($('v5WeightEvolution'))$('v5WeightEvolution').textContent=`${(first-latest).toFixed(1)} kg`;

  let milestone=goal;
  if(latest>goal){
    const candidate=Math.max(goal,Math.floor((latest-0.01)/5)*5);
    milestone=candidate>=latest?Math.max(goal,candidate-5):candidate;
  }else if(latest<goal){
    const candidate=Math.min(goal,Math.ceil((latest+0.01)/5)*5);
    milestone=candidate<=latest?Math.min(goal,candidate+5):candidate;
  }
  if($('v5NextMilestone'))$('v5NextMilestone').textContent=`${milestone.toFixed(1)} kg`;

  const values=weights.map(x=>num(x.weight)).concat([goal]);
  let min=Math.min(...values)-1;
  let max=Math.max(...values)+1;
  if(max-min<2){max+=1;min-=1}

  const pad={l:42,r:18,t:20,b:34};
  const chartW=width-pad.l-pad.r;
  const chartH=height-pad.t-pad.b;

  ctx.strokeStyle='rgba(255,255,255,.10)';
  ctx.lineWidth=1;
  for(let i=0;i<4;i++){
    const y=pad.t+(chartH/3)*i;
    ctx.beginPath();
    ctx.moveTo(pad.l,y);
    ctx.lineTo(width-pad.r,y);
    ctx.stroke();
  }

  const xFor=i=>pad.l+(weights.length===1?chartW/2:(chartW*i/(weights.length-1)));
  const yFor=value=>pad.t+(max-value)/(max-min)*chartH;

  ctx.strokeStyle='#d7a62f';
  ctx.lineWidth=3;
  ctx.beginPath();
  weights.forEach((item,index)=>{
    const x=xFor(index);
    const y=yFor(num(item.weight));
    index===0?ctx.moveTo(x,y):ctx.lineTo(x,y);
  });
  ctx.stroke();

  ctx.fillStyle='#d7a62f';
  weights.forEach((item,index)=>{
    ctx.beginPath();
    ctx.arc(xFor(index),yFor(num(item.weight)),4,0,Math.PI*2);
    ctx.fill();
  });

  const goalY=yFor(goal);
  ctx.strokeStyle='#4aa9ff';
  ctx.setLineDash([6,5]);
  ctx.beginPath();
  ctx.moveTo(pad.l,goalY);
  ctx.lineTo(width-pad.r,goalY);
  ctx.stroke();
  ctx.setLineDash([]);

  ctx.fillStyle='#4aa9ff';
  ctx.font='12px sans-serif';
  ctx.textAlign='right';
  ctx.fillText(`Objetivo ${goal.toFixed(1)} kg`,width-pad.r,goalY-6);
}

