function getTodayRecord(){
  const date=today();
  let record=db.daily.find(x=>x.date===date);

  if(!record){
    record={
      id:crypto.randomUUID(),
      date,
      type:'Descanso',
      water:0,
      goal:1900,
      breakfast:0,
      lunch:0,
      snack:0,
      dinner:0,
      coffee:0,
      total:0,
      creatine:false,
      omega:false,
      whey:false,
      carnitine:false,
      notes:''
    };
    db.daily.push(record);
  }

  return record;
}

function refreshWaterQuickButton(){
  const record=db.daily.find(x=>x.date===today());
  const water=record?num(record.water):0;
  const goal=num(db.goals.water)||3000;
  const percentage=Math.min(100,water/goal*100);

  const text=$('v5WaterStat');
  const bar=$('v5WaterBar');
  if(text)text.textContent=`${water} / ${goal} ml`;
  if(bar)bar.style.width=`${percentage}%`;

  if($('dDate') && $('dDate').value===today() && $('dWater')){
    $('dWater').value=water;
    if(typeof refreshWaterQuick==='function')refreshWaterQuick();
  }
}

function addQuickWater(){
  const record=getTodayRecord();
  const previous=num(record.water);

  waterHistory.push(previous);
  record.water=previous+500;

  localStorage.setItem(K,JSON.stringify(db));
  refreshWaterQuickButton();
  refreshV5Dashboard();

  const button=$('v5WaterQuick');
  if(button){
    button.classList.add('water-added');
    const label=button.querySelector('strong');
    const small=button.querySelector('small');

    if(label)label.textContent=`${record.water} ML`;
    if(small)small.textContent='Água registada';

    setTimeout(()=>{
      button.classList.remove('water-added');
      if(label)label.textContent='ÁGUA +500 ML';
      if(small)small.textContent='Adicionar ingestão';
    },900);
  }
}


function refreshCoffeeUI(){
  const field=$('dCoffee');
  const count=field?num(field.value):0;
  const total=$('coffeeQuickTotal');
  const status=$('coffeeStatus');
  if(total)total.textContent=`${count} ${count===1?'café':'cafés'} · ${count*2} kcal`;
  if(status){
    status.className='coffee-status';
    if(count<3)status.textContent='Zona segura: até 2 cafés';
    else if(count===3){status.textContent='⚠ Atenção: chegaste ao 3.º café';status.classList.add('warning');}
    else{status.textContent='🔴 RED LINE: mais de 3 cafés';status.classList.add('redline');}
  }
  const button=$('v5CoffeeQuick');
  if(button){
    button.classList.toggle('coffee-warning',count===3);
    button.classList.toggle('coffee-redline',count>3);
    const small=button.querySelector('small');
    if(small)small.textContent=`${count} ${count===1?'café':'cafés'} hoje`;
  }
  live();
}
function setCoffeeCount(count,showAlert=false){
  count=Math.max(0,num(count));
  const date=$('dDate')?.value||today();
  let record=db.daily.find(x=>x.date===date);
  if(!record){record=date===today()?getTodayRecord():{id:crypto.randomUUID(),date,type:'Descanso',water:0,goal:1900,breakfast:0,lunch:0,snack:0,dinner:0,coffee:0,total:0,creatine:false,omega:false,whey:false,carnitine:false,notes:''};if(date!==today())db.daily.push(record);}
  record.coffee=count;
  record.total=num(record.breakfast)+num(record.lunch)+num(record.snack)+num(record.dinner)+(count*2);
  if($('dCoffee') && ($('dDate')?.value||today())===date)$('dCoffee').value=count;
  localStorage.setItem(K,JSON.stringify(db));
  refreshCoffeeUI();
  refreshV5Dashboard();
  if(showAlert&&count===3)alert('⚠ Atenção: chegaste ao 3.º café de hoje.');
  if(showAlert&&count>3)alert('🔴 RED LINE: ultrapassaste os 3 cafés de hoje.');
}
function addQuickCoffee(){
  const record=getTodayRecord();
  setCoffeeCount(num(record.coffee)+1,true);
}
if($('addCoffee'))$('addCoffee').onclick=()=>setCoffeeCount(num($('dCoffee').value)+1,true);
if($('removeCoffee'))$('removeCoffee').onclick=()=>setCoffeeCount(num($('dCoffee').value)-1,false);

function renderMainCalendar(){
  const title=$('calendarTitle');
  const grid=$('calendar');
  if(!title||!grid)return;

  const current=calendarCursor||new Date();
  const year=current.getFullYear();
  const month=current.getMonth();
  const todayDate=todayISO();

  title.textContent=new Intl.DateTimeFormat('pt-PT',{
    month:'long',
    year:'numeric'
  }).format(current);

  const totalDays=new Date(year,month+1,0).getDate();
  const firstDay=(new Date(year,month,1).getDay()+6)%7;
  let output='';

  for(let i=0;i<firstDay;i++)output+='<div class="calendar-empty"></div>';

  for(let day=1;day<=totalDays;day++){
    const date=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
    const daily=db.daily.find(x=>x.date===date);
    const hasTraining=db.training.some(x=>x.date===date)||(db.hiit||[]).some(x=>x.date===date);
    const hasCardio=(db.cardio||[]).some(x=>x.date===date);

    let status='';
    if(hasTraining||hasCardio)status='train';

    const todayClass=date===todayDate?' today':'';
    output+=`<button type="button" class="day ${status}${todayClass}" data-date="${date}">${day}</button>`;
  }

  grid.innerHTML=output;
  grid.querySelectorAll('[data-date]').forEach(button=>{
    button.onclick=()=>openCalendarDay(button.dataset.date);
  });
}


const v5GoalMinus=$('v5GoalMinus');
const v5GoalPlus=$('v5GoalPlus');
function changeMissionGoal(delta){
  const input=$('v5GoalWeightInput');
  if(!input)return;
  const current=num(input.value)||num(db.goals.weight)||75;
  input.value=Math.max(30,Math.min(250,current+delta)).toFixed(1);
}
if(v5GoalMinus)v5GoalMinus.onclick=()=>changeMissionGoal(-0.5);
if(v5GoalPlus)v5GoalPlus.onclick=()=>changeMissionGoal(0.5);

const v5SaveWeightGoal=$('v5SaveWeightGoal');
if(v5SaveWeightGoal){
  v5SaveWeightGoal.onclick=()=>{
    const goal=num($('v5GoalWeightInput').value);
    if(!goal||goal<=0){
      alert('Indica um objetivo de peso válido.');
      return;
    }

    db.goals.weight=goal;
    if($('goalWeight'))$('goalWeight').value=goal;
    localStorage.setItem(K,JSON.stringify(db));
    drawGoalProgressChart();
    alert('Objetivo atualizado');
  };
}

